export interface LpMonitorRuleInputConfig {
  min: number;
  max?: number;
  step: number;
  fallback: number;
}

export interface LpMonitorRuleDefinition {
  id: string;
  scope: 'pool' | 'position';
  label: string;
  enabledKey: string;
  valueKey: string;
  input: LpMonitorRuleInputConfig;
  cli: {
    enabledArg: string;
    valueArg: string;
  };
}

export interface LpMonitorRulesConfig {
  poolImbalanceEnabled: boolean;
  poolImbalanceRatioLimit: number;
  noCompetitiveYieldEnabled: boolean;
  noCompetitiveYieldMultiplier: number;
  rebalanceRiskEnabled: boolean;
  rebalanceRiskBoundaryRatio: number;
  highTvlShareEnabled: boolean;
  highTvlShareThreshold: number;
  [key: string]: boolean | number;
}

export const LP_MONITOR_DEFAULT_RULES_CONFIG: Readonly<LpMonitorRulesConfig>;
export const LP_MONITOR_RULE_SCHEMA: readonly LpMonitorRuleDefinition[];

export function encodeLpMonitorPoolOverrides(value: unknown): string;
export function decodeLpMonitorPoolOverrides(value: unknown): unknown[];
export function encodeLpMonitorTargetOverrides(value: unknown): string;
export function decodeLpMonitorTargetOverrides(value: unknown): unknown[];
export function createDefaultLpMonitorRulesConfig(): LpMonitorRulesConfig;
export function normalizeLpMonitorRulesConfig(
  input: Partial<Record<keyof LpMonitorRulesConfig, unknown>> | null | undefined,
  fallback?: LpMonitorRulesConfig
): LpMonitorRulesConfig;
export function buildLpMonitorCliArgs(params: {
  owner?: string;
  owners?: string[];
  scopeOwner?: string;
  rules: LpMonitorRulesConfig;
  selectedChains?: string[];
  selectedDexNames?: string[];
  poolOverrides?: unknown[];
  targetOverrides?: unknown[];
}): string[];
